insert into places (id, name, type, description, map_url, coords, status)
select (r->>'id')::uuid as id,
       nullif(r->>'name','') as name,
       (r->>'type')::place_type as type,
       nullif(r->>'description','') as description,
       nullif(r->>'map_url','') as map_url,
       nullif(r->>'coords','') as coords,
       coalesce(nullif(r->>'status',''),'draft')::content_status as status
